    def generate_token(request, refresh_token=False):
        # Create claims dictionary
        claims = {
            'iss': kwargs.get('iss'),
            'sub': kwargs.get('sub'),
            'aud': kwargs.get('aud'),
        }

        # Add scope if available
        if hasattr(request, 'scopes') and request.scopes:
            claims['scope'] = ' '.join(request.scopes)

        # Add user_id if available
        if hasattr(request, 'user_id'):
            claims['user_id'] = request.user_id

        # Remove None values
        claims = {k: v for k, v in claims.items() if v is not None}

        # Generate the signed token
        return common.generate_signed_token(private_pem, claims)

